class TaskBinding {static Object queue(int kind,int n){return switch(kind){case 0->new FixedQueue(n);case 1->new CircularQueue(n);default->new DynQueue(n);};}static void put(Object x,char c){((ICharQ)x).put(c);}static char get(Object x){return ((ICharQ)x).get();}static void transfer(Object s,Object d,int n){QueueTransfer.transfer((ICharQ)s,(ICharQ)d,n);}}
